let list = '';
for (const id in groups) {
 const g = groups[id];
 if (id.endsWith('@g.us')) {
 list += `• ${id.split('@')[0]}: welcome=${g.welcome ? '✅' : '❌'}, delswgc=${g.delswgc ? '✅' : '❌'}\n`;
 }
}
m.reply(list || 'Tidak ada grup terdaftar');

let chats = global.db.data.chats || {};
let updated = 0;
for (let id in chats) {
 if (id.endsWith('@g.us')) {
 let chat = chats[id];
 let changed = false;
 if (chat.welcome === true) {
 chat.welcome = false;
 changed = true;
 }
 if (chat.delswgc === true) {
 chat.delswgc = false;
 changed = true;
 }
 if (changed) updated++;
 }
}
global.__DB_DIRTY__ = true;
await global.db.write();
m.reply(`✅ Welcome dan delswgc dimatikan di ${updated} grup.`);

